import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))

        mx = max(a)
        mn = min(a)

        if mx == mn:
            results.append(str(sum(a)))
        else:
            diff = mx - mn
            results.append(str(diff * n))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
